using System.Buffers.Binary;
using System.IO.Compression;
using System.Text;
using CthExtract.Gta.Audio;
using CthExtract.Gta.Crypto;
using CthExtract.Gta.Rpf;
using CthExtract.Gta.Tests.Synth;
using Xunit;

namespace CthExtract.Gta.Tests;

/// <summary>Damaged size fields in archives and audio must fail one asset with a clear reason, never allocate
/// gigabytes or read outside the archive an entry belongs to. All data here is generated by the test.</summary>
public class RobustnessTests
{
    private static byte[] Deflate(byte[] data)
    {
        using var ms = new MemoryStream();
        using (var ds = new DeflateStream(ms, CompressionLevel.Fastest, leaveOpen: true)) ds.Write(data);
        return ms.ToArray();
    }

    [Fact]
    public void Inflate_stops_at_the_recorded_size()
    {
        var zeros = new byte[4 * 1024 * 1024];
        var packed = Deflate(zeros);
        Assert.True(packed.Length < 64 * 1024); // a small "bomb"
        Assert.Equal(zeros.Length, RpfArchive.Inflate(packed, zeros.Length, "ok").Length);
        var e = Assert.Throws<InvalidDataException>(() => RpfArchive.Inflate(packed, 1000, "bomb.bin"));
        Assert.Contains("bomb.bin", e.Message);
        Assert.Contains("recorded size 1000", e.Message);
    }

    [Fact]
    public void Inflate_with_a_huge_recorded_size_does_not_preallocate_it()
    {
        var text = Encoding.UTF8.GetBytes(string.Concat(Enumerable.Repeat("rpf ", 1000)));
        // a garbage size field of ~2 GiB used to become the MemoryStream's initial capacity
        var got = RpfArchive.Inflate(Deflate(text), int.MaxValue - 16, "big");
        Assert.Equal(text, got);
    }

    [Fact]
    public void Entry_pointing_outside_its_nested_archive_is_refused()
    {
        var keys = new SynthKeys(5);
        var inner = new RpfWriter(RpfEnc.Open, keys).AddBinary("a.txt", Encoding.UTF8.GetBytes(new string('x', 3000)));
        var innerBytes = inner.Build("inner.rpf");
        // entry 1 = a.txt (entry 0 is the root directory); OPEN TOC: bits 40..63 of the first u64 are the 512-byte offset
        int e1 = 16 + 16;
        ulong q = BinaryPrimitives.ReadUInt64LittleEndian(innerBytes.AsSpan(e1));
        q = (q & 0x000000FFFFFFFFFFUL) | ((ulong)0x200 << 40); // 0x200 * 512 = 256 KiB: past the nested archive's end
        BinaryPrimitives.WriteUInt64LittleEndian(innerBytes.AsSpan(e1), q);
        var outer = new RpfWriter(RpfEnc.Open, keys)
            .AddBinary("levels/inner.rpf", innerBytes)
            .AddBinary("pad.bin", new byte[600 * 1024]); // the outer file is long enough that only the window check can catch it
        using var tmp = new TempDir();
        using var f = new RpfFile(tmp.File("x.rpf", outer.Build("x.rpf")));
        var a = RpfArchive.Open(f, "x.rpf", new GtaKeys());
        var n = a.OpenNested(a.Files.Single(x => x.Path == "levels/inner.rpf"));
        var entry = n.Files.Single(x => x.Path == "a.txt");
        var ex = Assert.Throws<InvalidDataException>(() => n.ReadBinary(entry));
        Assert.Contains("outside its archive", ex.Message);
    }

    [Fact]
    public void Multichannel_awc_with_a_huge_sample_count_does_not_preallocate_it()
    {
        // one multichannel stream (id 0): 0x48 stream header + 0x55 data; channel sample count 0x7FFFFFF0
        var d = new byte[0x2000];
        BinaryPrimitives.WriteUInt32LittleEndian(d, AwcFile.MagicLe);
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(4), 0xFF000001);
        BinaryPrimitives.WriteInt32LittleEndian(d.AsSpan(8), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(16), 2u << 29); // id 0, 2 tags
        int hdr = 0x100, data = 0x800, dataLen = 0x1000;
        BinaryPrimitives.WriteUInt64LittleEndian(d.AsSpan(20), ((ulong)0x48 << 56) | ((ulong)0x20 << 28) | (uint)hdr);
        BinaryPrimitives.WriteUInt64LittleEndian(d.AsSpan(28), ((ulong)0x55 << 56) | ((ulong)dataLen << 28) | (uint)data);
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(hdr), 1);       // blocks
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(hdr + 4), 0x1000); // block size
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(hdr + 8), 1);   // channels
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(hdr + 0x0C), 0x1234);
        BinaryPrimitives.WriteUInt32LittleEndian(d.AsSpan(hdr + 0x10), 0x7FFFFFF0); // samples
        d[hdr + 0x0C + 0x0C] = 4; // IMA
        var awc = AwcFile.Parse(d, null);
        var s = Assert.Single(awc.Streams);
        // the block layout is garbage: it may fail, but only with a bounded allocation and a normal exception
        try { s.DecodePcm(); }
        catch (Exception e) { Assert.IsNotType<OutOfMemoryException>(e); }
    }
}
